                <circle cx="75" cy="65" r="6" fill="white" />
                {/* Red Swoosh/Arc */}
                <path d="M10 70 C 10 20, 40 5, 80 15" fill="none" stroke="#D92323" strokeWidth="6" strokeLinecap="round" />
