                <span className="font-display font-black text-2xl leading-none text-brand-red italic tracking-tighter">
                  C.A.
                </span>
                <span className="font-display font-black text-2xl leading-none text-white ml-1 tracking-tight">
                  RODRIGUES
                </span>
              </div>
              <span className="text-[10px] font-bold tracking-[0.3em] uppercase text-gray-400 pl-1">
